using System.Collections.Generic;
using System.Linq;
using System.Text.RegularExpressions;
using Oathdeep.Audio;
using UnityEditor;
using UnityEngine;

namespace Oathdeep.EditorTools
{
    /// <summary>Stage 2b: audio import settings + the AudioLibrary (clips generated by tools/audio/*.py).</summary>
    public static partial class OathdeepSetup
    {
        const string AudioDir = Root + "/Audio";
        static AudioLibrary audioLibrary;

        // volume, pitch jitter, min interval between repeats
        static readonly Dictionary<Sfx, (float vol, float jitter, float interval)> SfxMix = new Dictionary<Sfx, (float, float, float)>
        {
            [Sfx.Swing] = (0.7f, 0.08f, 0.05f), [Sfx.SwingHeavy] = (0.8f, 0.06f, 0.05f), [Sfx.Hit] = (0.9f, 0.1f, 0.03f),
            [Sfx.HitCrit] = (1f, 0.05f, 0.05f), [Sfx.PlayerHurt] = (0.9f, 0.05f, 0.15f), [Sfx.EnemyDeath] = (0.8f, 0.1f, 0.05f),
            [Sfx.SlimeSquish] = (0.6f, 0.15f, 0.08f), [Sfx.Dodge] = (0.6f, 0.1f, 0.1f), [Sfx.Bash] = (0.9f, 0.05f, 0.1f),
            [Sfx.ArrowShoot] = (0.6f, 0.12f, 0.05f), [Sfx.Spike] = (0.5f, 0.1f, 0.2f), [Sfx.BossSlam] = (1f, 0.04f, 0.2f),
            [Sfx.BossCast] = (0.9f, 0f, 0.5f), [Sfx.BossRoar] = (1f, 0f, 1f), [Sfx.Coin] = (0.55f, 0.06f, 0.04f),
            [Sfx.Potion] = (0.8f, 0f, 0.2f), [Sfx.ItemPickup] = (0.9f, 0f, 0.2f), [Sfx.ChestOpen] = (0.9f, 0f, 0.2f),
            [Sfx.Break] = (0.7f, 0.12f, 0.04f), [Sfx.DoorSlam] = (0.85f, 0.05f, 0.2f), [Sfx.DoorOpen] = (0.6f, 0.05f, 0.2f),
            [Sfx.Spawn] = (0.5f, 0.08f, 0.15f), [Sfx.RoomClear] = (0.85f, 0f, 0.5f), [Sfx.UiClick] = (0.6f, 0.05f, 0.03f),
            [Sfx.UiConfirm] = (0.7f, 0f, 0.05f),
        };

        static void BuildAudio(List<string> log)
        {
            var entries = new List<AudioLibrary.Entry>();
            foreach (Sfx id in System.Enum.GetValues(typeof(Sfx)))
            {
                string path = $"{AudioDir}/SFX/{Snake(id.ToString())}.wav";
                ConfigureClip(path, AudioClipLoadType.DecompressOnLoad, AudioCompressionFormat.ADPCM, mono: true);
                var (vol, jitter, interval) = SfxMix[id];
                entries.Add(new AudioLibrary.Entry
                {
                    Id = id, Clip = Load<AudioClip>(path), Volume = vol, PitchJitter = jitter, MinInterval = interval,
                });
            }

            audioLibrary = LoadOrCreate<AudioLibrary>(DataDir + "/AudioLibrary.asset");
            audioLibrary.sfx = entries.ToArray();
            audioLibrary.musicTitle = Music("music_title", true);
            audioLibrary.musicCrypt = Music("music_crypt", true);
            audioLibrary.musicBoss = Music("music_boss", true);
            audioLibrary.stingVictory = Music("sting_victory", false);
            audioLibrary.stingGameOver = Music("sting_gameover", false);
            EditorUtility.SetDirty(audioLibrary);
            log.Add($"audio: {entries.Count} sfx, 3 music loops, 2 stingers");
        }

        static AudioClip Music(string name, bool loop)
        {
            string path = $"{AudioDir}/Music/{name}.wav";
            // Loops stream (low memory); stingers are short so they stay compressed in memory.
            ConfigureClip(path, loop ? AudioClipLoadType.Streaming : AudioClipLoadType.CompressedInMemory,
                          AudioCompressionFormat.Vorbis, mono: false, quality: 0.55f);
            return Load<AudioClip>(path);
        }

        static void ConfigureClip(string path, AudioClipLoadType load, AudioCompressionFormat format, bool mono, float quality = 0.7f)
        {
            var importer = AssetImporter.GetAtPath(path) as AudioImporter;
            if (importer == null) throw new System.IO.FileNotFoundException("Audio clip missing (run tools/audio/sfx.py + music.py)", path);
            var s = importer.defaultSampleSettings;
            s.loadType = load;
            s.compressionFormat = format;
            s.quality = quality;
            s.preloadAudioData = true;
            importer.defaultSampleSettings = s;
            importer.forceToMono = mono;
            importer.loadInBackground = false;
            importer.SaveAndReimport();
        }

        static T Load<T>(string path) where T : Object
        {
            var asset = AssetDatabase.LoadAssetAtPath<T>(path);
            if (asset == null) throw new System.IO.FileNotFoundException($"{typeof(T).Name} missing", path);
            return asset;
        }

        static string Snake(string camel) => Regex.Replace(camel, "(?<!^)([A-Z])", "_$1").ToLowerInvariant();
    }
}
